--- index.html
+++ index.html
@@ -23,4 +23,36 @@
 </aside></main>
 <footer class="footer"><span>✦ &nbsp; EVERY ENDING IS A BEGINNING</span><div class="controls"><span><b>WASD</b> move</span><span><b>E</b> possess / interact</span><span><b>SPACE</b> strike</span><span><b>Q</b> unbind</span></div></footer>
 </div>
 <script>
+(()=>{
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
+const W=960,H=600,keys={},rand=(n)=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
+const names={log:['Mossling','Thornback','Elderbark','Worldroot'],corpse:['Gravekin','Hollowguard','Dreadknight','Warden of Dust'],lamp:['Gloam Wisp','Lantern Wight','Candle Saint','Sunless Beacon'],bones:['Bonebound','Rattleclaw','Marrow Beast','Ossuary King']};
+const desc={log:'A fallen branch remembers reaching for the light. It is small, quick, and stubbornly alive.',corpse:'A peaceful body, mended by your presence. A sturdy beginning for a soul with unfinished business.',lamp:'A forgotten lantern finds a flame again. It floats lightly and shines into the dark.',bones:'Old bones knit together around your spark. Brittle no longer, they hunger for a purpose.'};
+let game={started:false,last:0,player:{x:475,y:310,dx:0,dy:1,health:100,max:100,attack:0,dash:0,invuln:0},vessel:null,essence:0,progress:0,kills:0,awakened:0,toastTimer:0,particles:[],time:0,won:false};
+const vessels=[{kind:'corpse',x:448,y:335},{kind:'log',x:245,y:286},{kind:'lamp',x:726,y:330},{kind:'bones',x:676,y:202}].map((v,i)=>({...v,level:0,alive:true,id:i}));
+const relics=[{x:160,y:150,on:false},{x:800,y:150,on:false},{x:480,y:495,on:false}];
+let enemies=[{x:284,y:177,hp:2,max:2,alive:true,seed:1},{x:736,y:173,hp:2,max:2,alive:true,seed:2},{x:532,y:430,hp:2,max:2,alive:true,seed:3}];
+function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');game.toastTimer=2.3}
+function current(){return game.vessel}
+function playerSpeed(){return !current()?150:current().kind==='lamp'?174:current().kind==='log'?161:current().kind==='bones'?143:132}
+function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
+function start(){if(game.started)return;game.started=true;document.getElementById('intro').classList.add('hidden');game.last=performance.now();requestAnimationFrame(frame);toast('The glade is listening. Find a form.');}
+document.getElementById('start').addEventListener('click',start);
+window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(!game.started&&(k==='enter'||k===' '))start();if(game.started&&!e.repeat){if(k==='e')interact();if(k==='q')unbind();if(k===' '||k==='j')attack();if(k==='shift')dash()}});
+window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
+function interact(){const p=game.player;let nearV=null,vd=72;for(const v of vessels){let d=dist(p,v);if(d<vd){nearV=v;vd=d}}
+ let nearR=null,rd=61;for(const r of relics){let d=dist(p,r);if(d<rd){nearR=r;rd=d}}
+ if(nearR){if(!nearR.on){nearR.on=true;game.awakened++;game.player.health=Math.min(game.player.max,game.player.health+24);burst(nearR.x,nearR.y,'#d7e99d',20);toast(`Relic awakened · ${game.awakened} of 3`);if(game.awakened===3){game.won=true;toast('The glade remembers the sun. You are its new heart.')}}else toast('This relic already shines.');return}
+ if(nearV){if(game.vessel===nearV){toast('This form is already yours.');return}game.vessel=nearV;nearV.alive=true;game.progress=nearV.level;game.player.max=100+nearV.level*22;game.player.health=game.player.max;burst(nearV.x,nearV.y,'#b9e8a4',15);toast(`${names[nearV.kind][nearV.level]} awakened`);updateHud();return}
+ toast('Drift closer to a vessel or a sleeping relic.');}
+function unbind(){if(!game.vessel){toast('You are already unbound.');return}let v=game.vessel;v.x=game.player.x;v.y=game.player.y;game.vessel=null;game.player.max=100;game.player.health=Math.min(game.player.health,100);burst(game.player.x,game.player.y,'#b9e8ed',12);toast('Your soul slips free. The body rests, whole again.');updateHud()}
+function attack(){const p=game.player;if(p.attack>0)return;p.attack=.38;let hits=0;for(const en of enemies){if(!en.alive)continue;let d=dist(p,en);let dot=(en.x-p.x)*p.dx+(en.y-p.y)*p.dy;if(d<74&&(dot>-15||d<32)){en.hp--;burst(en.x,en.y,'#ccf2d1',6);if(en.hp<=0){en.alive=false;game.essence++;game.kills++;game.progress++;burst(en.x,en.y,'#d9ed9b',18);toast('+1 ESSENCE · the dark loosens its grip');if(game.vessel&&game.vessel.level<3&&game.progress>=3){game.progress-=3;game.vessel.level++;game.player.max+=22;game.player.health=game.player.max;toast(`${names[game.vessel.kind][game.vessel.level]} · FORM EVOLVED`)}hits++}}}if(!hits)burst(p.x+p.dx*35,p.y+p.dy*35,'#9de9c0',4);updateHud()}
+function dash(){if(game.player.dash>0)return;game.player.dash=.85;game.player.invuln=.32;let p=game.player;p.x+=p.dx*70;p.y+=p.dy*70;clamp(p);burst(p.x,p.y,'#9adbe0',8)}
+function clamp(p){p.x=Math.max(42,Math.min(W-42,p.x));p.y=Math.max(74,Math.min(H-38,p.y))}
+function burst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=20+Math.random()*110;game.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+Math.random()*.55,max:.9,color,size:2+Math.random()*3})}}
+function update(dt){let p=game.player;game.time+=dt;p.attack=Math.max(0,p.attack-dt);p.dash=Math.max(0,p.dash-dt);p.invuln=Math.max(0,p.invuln-dt);game.toastTimer-=dt;if(game.toastTimer<=0)document.getElementById('toast').classList.remove('show');
+ let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(mx||my){let l=Math.hypot(mx,my);mx/=l;my/=l;p.dx=mx;p.dy=my;p.x+=mx*playerSpeed()*dt;p.y+=my*playerSpeed()*dt;clamp(p)}
+ for(const en of enemies){if(!en.alive){en.respawn=(en.respawn||5)-dt;if(en.respawn<=0){en.alive=true;en.hp=en.max;en.x=80+rand(en.seed+game.time|0)*800;en.y=110+rand(en.seed+game.time*2|0)*390;en.respawn=0}continue}let d=dist(p,en);if(d<300){let speed=game.vessel?31:22;if(d>25){en.x+=(p.x-en.x)/d*speed*dt;en.y+=(p.y-en.y)/d*speed*dt}if(d<25&&game.vessel&&p.invuln<=0){p.health-=13*dt;if(p.health<=0){p.health=p.max*.55;en.x+=80;toast('Your vessel mends itself. Keep moving.');burst(p.x,p.y,'#e79582',14)}}}}
+ for(let i=game.particles.length-1;i>=0;i--){let a=game.particles[i];a.x+=a.vx*dt;a.y+=a.vy*dt;a.vx*=.96;a.vy*=.96;a.life-=dt;if(a.life<=0)game.particles.splice(i,1)}updateHud()}
+function updateHud(){let v=game.vessel,p=game.player;document.getElementById('formName').textContent=v?names[v.kind][v.level]:'Wandering Soul';document.getElementById('formType').textContent=v?`${v.kind==='corpse'?'REGENERATED CORPSE':v.kind==='log'?'LIVING WOOD':v.kind==='lamp'?'ANIMATED RELIC':'REASSEMBLED BONES'} · FORM ${v.level}`:'UNBOUND · FORM 0';document.getElementById('formDescription').textContent=v?desc[v.kind]: 'A spark looking for somewhere to belong. Drift close to a vessel and press E.';document.getElementById('healthText').textContent=v?`${Math.ceil(p.health)} / ${p.max}`:'—';document.getElementById('healthLabel').textContent=v?`${Math.ceil(p.health)} / ${p.max}`:'—';document.getElementById('healthBar').style.width=v?`${Math.max(0,p.health/p.max*100)}%`:'100%';document.getElementById('essenceText').textContent=game.essence;document.getElementById('powerText').textContent=v?`${1+v.level*2} · ${v.kind==='lamp'?'LIGHT':'SOUL'}`:'—';document.getElementById('evoText').textContent=v?`${v.level} / 3`:'0 / 3';document.getElementById('xpLabel').textContent=`${game.progress} / 3`;document.getElementById('xpBar').style.width=`${game.progress/3*100}%`;document.getElementById('goal0').classList.toggle('done',!!v);document.getElementById('goal0').querySelector('.check').textContent=v?'✓':'';document.getElementById('goal1').classList.toggle('done',game.essence>=3);document.getElementById('goal1').querySelector('.check').textContent=game.essence>=3?'✓':'';document.getElementById('goal2').classList.toggle('done',game.awakened>=3);document.getElementById('goal2').querySelector('.check').textContent=game.awakened>=3?'✓':'';document.querySelector('.objective b').textContent=game.awakened>=3?'The glade is restored':`Awaken the three relics · ${game.awakened}/3`}

