const px=(x,y,w,h,c)=>{ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))};
function drawGround(){px(0,0,W,H,'#17221d');for(let y=44;y<H;y+=32)for(let x=28;x<W;x+=32){let r=rand((x+1)*3+y*17);px(x,y,31,31,r>.76?'#1a2720':r<.12?'#19251f':'#18251f');if(r>.79){px(x+rand(x+y)*24,y+rand(y+x)*20,2,2,'#293a2c');px(x+9,y+22,2,2,'#213128')}if(r<.06)px(x+21,y+8,3,2,'#28382b')}
 // winding ancient path
 ctx.fillStyle='#252c22';ctx.beginPath();ctx.moveTo(398,600);ctx.bezierCurveTo(450,488,350,448,430,378);ctx.bezierCurveTo(510,304,580,310,515,225);ctx.bezierCurveTo(468,158,512,110,505,55);ctx.lineTo(545,55);ctx.bezierCurveTo(542,131,510,166,549,218);ctx.bezierCurveTo(628,316,544,337,468,402);ctx.bezierCurveTo(407,457,497,506,455,600);ctx.closePath();ctx.fill();
 // broken paving flecks
 for(let i=0;i<42;i++){let x=380+rand(i+8)*180,y=68+rand(i+99)*510;if(x>W-50)continue;px(x,y,5+rand(i)*8,2,'#33372a')}
 // forest edge and pixel trees
 for(let i=0;i<17;i++){let x=i*61-8,y=rand(i+55)*33+20;tree(x,y,1+rand(i)*.45)}for(let i=0;i<18;i++){let x=i*59+12,y=551+rand(i+91)*34;tree(x,y,1+rand(i+33)*.4)}
 for(let i=0;i<5;i++){tree(28+rand(i+400)*60,130+i*82,.8);tree(870+rand(i+490)*64,135+i*77,.85)}
 // distant bioluminescent motes
 for(let i=0;i<20;i++){let x=rand(i+210)*W,y=65+rand(i+570)*480;let glow=.2+.25*Math.sin(game.time*2+i);ctx.globalAlpha=glow;px(x,y,2,2,i%2?'#a2cd85':'#8cbdc0')}ctx.globalAlpha=1;
 // outer boundary
 ctx.strokeStyle='#344339';ctx.lineWidth=2;ctx.strokeRect(34,49,892,507);vignette()}
function tree(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);px(-5,12,16,24,'#342c20');px(-1,15,6,20,'#51412a');px(-15,7,30,7,'#263b2b');px(-12,-1,25,11,'#29412c');px(-8,-9,17,12,'#315037');px(-4,-13,8,7,'#3b5a3a');px(-13,10,8,5,'#3d5736');px(6,3,7,6,'#355133');ctx.restore()}
function vignette(){let g=ctx.createRadialGradient(480,295,140,480,295,570);g.addColorStop(0,'#00000000');g.addColorStop(1,'#060b0bbb');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}
function shadow(x,y,w=30){ctx.fillStyle='#070a08aa';ctx.beginPath();ctx.ellipse(x,y,w/2,6,0,0,Math.PI*2);ctx.fill()}
function drawRelic(r,i){let glow=r.on?'#d9f09c':'#776e45',pulse=Math.sin(game.time*2+i)*2;ctx.globalAlpha=r.on?.24:.12;ctx.fillStyle=glow;ctx.beginPath();ctx.arc(r.x,r.y-14,38+pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;shadow(r.x,r.y+4,36);px(r.x-12,r.y-8,24,12,'#554c31');px(r.x-9,r.y-14,18,8,'#84774a');px(r.x-5,r.y-21,10,10,r.on?'#d4efa0':'#837e50');px(r.x-3,r.y-25,6,5,r.on?'#efffc0':'#aaa36a');px(r.x-2,r.y-19,3,7,r.on?'#f4ffd2':'#c6c17d');ctx.fillStyle=r.on?'#d7f0a2':'#a8a06a';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText(r.on?'AWAKENED':'SLEEPING RELIC',r.x,r.y+22)}
function drawVessel(v,x=v.x,y=v.y,isPlayer=false){let lev=v.level,glow=lev>0?['','#b0d785','#dcaa81','#daf0a3'][lev]:'#9bcf9a';shadow(x,y+3,v.kind==='log'?40:30);if(isPlayer){ctx.globalAlpha=.16;ctx.fillStyle=glow;ctx.beginPath();ctx.arc(x,y-20,34+lev*5,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
 if(v.kind==='corpse'){// restored wanderer, then increasingly armored
 px(x-5,y-37,11,10,'#c7a77b');px(x-8,y-28,16,19,lev>=2?'#54635a':'#68715a');px(x-12,y-27,5,14,'#53604c');px(x+7,y-27,5,14,'#53604c');px(x-8,y-11,6,12,'#625544');px(x+2,y-11,6,12,'#655746');px(x-5,y-35,3,2,'#283528');px(x+3,y-35,3,2,'#283528');px(x-3,y-40,7,3,'#b7a078');if(lev>0){px(x-13,y-25,26,4,'#a4b181');px(x-10,y-3,20,3,'#837451')}if(lev>1){px(x-10,y-32,20,6,'#adbd8b');px(x-12,y-19,4,8,'#b8c88a');px(x+8,y-19,4,8,'#b8c88a')}if(lev>2){px(x-13,y-41,5,10,'#e1cf9a');px(x+8,y-41,5,10,'#e1cf9a');px(x-2,y-26,5,6,'#d7ed9f')}}
 else if(v.kind==='log'){px(x-12,y-27,24,25,lev>0?'#586744':'#64533a');px(x-9,y-32,18,8,'#78905a');px(x-6,y-36,12,6,'#9aa76a');px(x-8,y-3,6,7,'#493f2d');px(x+3,y-3,6,7,'#493f2d');px(x-4,y-22,3,3,'#d6ed9e');px(x+3,y-22,3,3,'#d6ed9e');if(lev>0){px(x-20,y-25,9,5,'#597347');px(x+11,y-25,9,5,'#597347');px(x-17,y-31,5,8,'#88945b');px(x+13,y-31,5,8,'#88945b')}if(lev>1){px(x-23,y-35,6,12,'#7c9c5e');px(x+16,y-35,6,12,'#7c9c5e');px(x-3,y-40,6,8,'#b0c978')}if(lev>2){px(x-28,y-40,7,4,'#c3d681');px(x+21,y-40,7,4,'#c3d681')}}
 else if(v.kind==='lamp'){let bob=Math.sin(game.time*3+x)*2; y-=bob;px(x-2,y-43,4,8,'#8e8056');px(x-10,y-35,20,4,'#928353');px(x-8,y-31,16,18,'#5b6350');px(x-5,y-28,10,12,lev>0?'#d3d991':'#d6bb72');px(x-12,y-17,24,4,'#84774f');px(x-8,y-13,4,9,'#81754d');px(x+4,y-13,4,9,'#81754d');px(x-5,y-25,3,4,'#fff0ad');if(lev>0){px(x-13,y-33,4,8,'#b4ce8d');px(x+9,y-33,4,8,'#b4ce8d')}if(lev>1){px(x-15,y-38,5,5,'#d1e4a0');px(x+10,y-38,5,5,'#d1e4a0');px(x-2,y-48,5,6,'#d8eca2')}if(lev>2){px(x-18,y-25,4,7,'#d8eba2');px(x+14,y-25,4,7,'#d8eba2')}}
 else {px(x-11,y-29,22,22,lev>0?'#b6b495':'#898b7d');px(x-6,y-37,12,11,'#c4c4a4');px(x-7,y-34,4,3,'#29322b');px(x+3,y-34,4,3,'#29322b');px(x-15,y-22,5,16,'#a4a48c');px(x+10,y-22,5,16,'#a4a48c');px(x-8,y-7,5,11,'#8d8a76');px(x+3,y-7,5,11,'#8d8a76');if(lev>0){px(x-14,y-38,5,9,'#d2d3b3');px(x+9,y-38,5,9,'#d2d3b3')}if(lev>1){px(x-18,y-28,5,8,'#d4d3b1');px(x+13,y-28,5,8,'#d4d3b1');px(x-3,y-28,6,5,'#e0eaa7')}if(lev>2){px(x-17,y-42,4,8,'#ece8c1');px(x+13,y-42,4,8,'#ece8c1')}}
 if(isPlayer){ // soul-fire eyes and a few bright sparks
 px(x-5,y-27,3,3,'#e6f4b4');px(x+3,y-27,3,3,'#e6f4b4');if(lev>0){px(x-1,y-20,3,5,'#9ce5c5')}}
}
function drawSoul(x,y){let bob=Math.sin(game.time*4)*3;shadow(x,y+4,22);ctx.globalAlpha=.18;ctx.fillStyle='#8de9e9';ctx.beginPath();ctx.arc(x,y-19+bob,23,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;px(x-4,y-27+bob,8,14,'#83d7d1');px(x-7,y-22+bob,14,9,'#b1f0dc');px(x-4,y-16+bob,8,6,'#ddf8c7');px(x-2,y-30+bob,4,4,'#e5f9c8');px(x-2,y-23+bob,2,3,'#344a42');px(x+3,y-23+bob,2,3,'#344a42');for(let i=0;i<3;i++){let a=game.time*1.7+i*2.1;px(x+Math.cos(a)*12-1,y-21+bob+Math.sin(a)*10,3,3,'#c8f1ba')}}
function drawEnemy(en){shadow(en.x,en.y+4,29);let bob=Math.sin(game.time*3+en.seed)*2;ctx.globalAlpha=.2;ctx.fillStyle='#c37f9e';ctx.beginPath();ctx.arc(en.x,en.y-21,22,0,7);ctx.fill();ctx.globalAlpha=1;px(en.x-8,en.y-35+bob,16,17,'#74536a');px(en.x-12,en.y-25+bob,24,11,'#58455d');px(en.x-7,en.y-20+bob,14,11,'#443e57');px(en.x-5,en.y-31+bob,3,3,'#f3bf97');px(en.x+3,en.y-31+bob,3,3,'#f3bf97');px(en.x-12,en.y-10,5,8,'#514559');px(en.x+7,en.y-10,5,8,'#514559');ctx.fillStyle='#d5a5a0';ctx.fillRect(en.x-9,en.y-45,18,2);ctx.fillStyle='#c78391';ctx.fillRect(en.x-9,en.y-45,18*(en.hp/en.max),2)}

